regex_once('backend/providers/vidy.py', '    def _request\\(\n        self,\n        url: str,\n        \\*,\n        params: dict\\[str, Any\\] \\| None = None,\n        referer: str \\| None = None,\n        accept: str = "application/json,text/plain,\\*/\\*",\n        timeout: float = 7\\.5,\n    \\) -> Any:\n.*?        return raw\n', '    def _request(\n        self,\n        url: str,\n        *,\n        params: dict[str, Any] | None = None,\n        referer: str | None = None,\n        accept: str = "application/json,text/plain,*/*",\n        timeout: float = 7.5,\n    ) -> Any:\n        headers = {\n            "User-Agent": USER_AGENT,\n            "Accept": accept,\n            "Accept-Language": "en-US,en;q=0.9",\n            "Referer": referer or f"{BASE_URL}/",\n            "Origin": BASE_URL,\n        }\n        self.log(f"GET {url}")\n        session = self.api_session if url.startswith(API_BASE) else self.db_session\n        try:\n            response = session.get(url, params=params, headers=headers, timeout=timeout)\n            response.raise_for_status()\n        except requests.RequestException as exc:\n            body = getattr(exc.response, "text", "") if getattr(exc, "response", None) is not None else ""\n            status = getattr(getattr(exc, "response", None), "status_code", "")\n            raise RuntimeError(f"HTTP {status or \'error\'} from {url}: {body[:240] or exc}") from exc\n\n        content_type = response.headers.get("Content-Type", "").lower()\n        raw = response.text\n        if "json" in content_type:\n            try:\n                return response.json()\n            except ValueError:\n                pass\n        stripped = raw.strip()\n        if stripped.startswith(("{", "[", \'"\')):\n            try:\n                return json.loads(stripped)\n            except json.JSONDecodeError:\n                pass\n        return raw\n')

